        LPOracleBase(
            vault_,
            IBasePool(address(pool_)),
            feeds,
            sequencerUptimeFeed,
            uptimeResyncWindow,
            shouldUseBlockTimeForOldestFeedUpdate,
            shouldRevertIfVaultUnlocked,
            version_
