        // `_computeMarketPriceBalances` fail with invalid prices, so we unfortunately cannot defer this validation
        // until the final tvl calculation loop.
        // Prices are normalized by dividing all prices by the minimum price. This ensures that the minimum price in
        // the price feed array is always 1, and it avoids the risk of division by zero in the computation of K.
        int256[] memory normalizedPrices = _ensureValidPricesAndNormalize(prices);

        // The TVL of the stable pool is computed by calculating the balances for the stable pool that would represent
        // the given price vector. To compute these balances, we need only the amplification parameter of the pool,
        // the invariant and the price vector.

        // Note that live balances are rounded down in the vault, and the invariant is computed rounding down as well,
        // so the resulting TVL will be rounded down. This is appropriate for an oracle, since it ensures that the
        // oracle price will not be higher than the true value of the pool. Additionally, using live balances ensures
        // that we are using the most up-to-date information about the pool state, including token rates.
        uint256[] memory currentBalancesLiveScaled18 = _vault.getCurrentLiveBalances(address(pool));
        uint256 invariant = pool.computeInvariant(currentBalancesLiveScaled18, Rounding.ROUND_DOWN);

        uint256[] memory marketPriceBalancesScaled18 = _computeMarketPriceBalances(invariant, normalizedPrices);

        for (uint256 i = 0; i < _totalTokens; i++) {
            tvl += prices[i].toUint256().mulDown(marketPriceBalancesScaled18[i]);
        }

        return tvl;
    }

    /**
     * @notice Computes a set of balances for a given price vector and a given invariant.
     * @dev The set of balances should meet two conditions:
     * 1. The invariant of the computed balances should be equal to the given invariant.
     * 2. The spot prices of the computed balances should be equal to the given price vector. In other words:
     *    `spotPrice(i, j) == prices[i] / prices[j]`
