// SPDX-License-Identifier: GPL-3.0-or-later

pragma solidity ^0.8.24;

import { AggregatorV3Interface } from "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import { SignedMath } from "@openzeppelin/contracts/utils/math/SignedMath.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import { ILPOracleBase } from "@balancer-labs/v3-interfaces/contracts/oracles/ILPOracleBase.sol";
import { IStablePool } from "@balancer-labs/v3-interfaces/contracts/pool-stable/IStablePool.sol";
import { Rounding } from "@balancer-labs/v3-interfaces/contracts/vault/VaultTypes.sol";
import { IBasePool } from "@balancer-labs/v3-interfaces/contracts/vault/IBasePool.sol";
import { IVault } from "@balancer-labs/v3-interfaces/contracts/vault/IVault.sol";

import { InputHelpers } from "@balancer-labs/v3-solidity-utils/contracts/helpers/InputHelpers.sol";
import { FixedPoint } from "@balancer-labs/v3-solidity-utils/contracts/math/FixedPoint.sol";
import { StableMath } from "@balancer-labs/v3-solidity-utils/contracts/math/StableMath.sol";

import { LPOracleBase } from "./LPOracleBase.sol";

/// @notice Oracle for stable pools.
contract StableLPOracle is LPOracleBase {
    using FixedPoint for uint256;
    using SafeCast for *;

    /// @notice The `k` parameter did not converge to the positive root.
    error KDidNotConverge();

    /**
     * @notice The minimum price of the feed array is too low.
     * @dev When the minimum price of the feed array is too low, `k` computation fails with division by zero.
     */
    error MinPriceTooLow();

    /**
     * @notice The ratio between the maximum and minimum prices is too high.
     * @dev When the ratio between the maximum and minimum prices is too high, `k` and invariant computations have a
     * high risk of not converging.
     */
    error PriceRatioTooHigh();

    int256 private constant _POSITIVE_ONE_INT = 1e18;
    uint256 private constant _K_MAX_ERROR = 1e4;
    int256 private constant _PRICE_RATIO_LIMIT = 1e7;
    int256 private constant _MIN_PRICE_LIMIT = 1e10;

    constructor(
        IVault vault_,
        IStablePool pool_,
        AggregatorV3Interface[] memory feeds,
        AggregatorV3Interface sequencerUptimeFeed,
        uint256 uptimeResyncWindow,
        bool shouldUseBlockTimeForOldestFeedUpdate,
        bool shouldRevertIfVaultUnlocked,
        uint256 version_
    )
        LPOracleBase(
            vault_,
            IBasePool(address(pool_)),
            feeds,
            sequencerUptimeFeed,
            uptimeResyncWindow,
            shouldUseBlockTimeForOldestFeedUpdate,
            shouldRevertIfVaultUnlocked,
            version_
        )
